window.CODE = Object.assign(window.CODE || {}, {"ch23/agents_as_tools.py":"\"\"\"The simplest multi-agent design: specialists wrapped as TOOLS of a supervisor agent.\n\nThe supervisor is an ordinary create_agent (Chapter 13). Calling a tool runs a whole specialist\nagent with a fresh context and returns its final answer. Parallel tool calls = parallel specialists.\n\nRun:  python agents_as_tools.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom langchain.agents import create_agent  # noqa: E402\nfrom langchain.agents.middleware import ModelCallLimitMiddleware  # noqa: E402\nfrom langchain_core.tools import tool  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\nfrom specialists import ask  # noqa: E402\n\n\n@tool\ndef ask_scheduling(task: str) -> str:\n    \"\"\"Ask the scheduling desk about doctors' days or whether a slot is possible. Give a complete, standalone task.\"\"\"\n    return ask(\"scheduling\", task)\n\n\n@tool\ndef ask_billing(task: str) -> str:\n    \"\"\"Ask the billing desk about bills, charges and fees. Include the bill number if the patient gave one.\"\"\"\n    return ask(\"billing\", task)\n\n\n@tool\ndef ask_insurance(task: str) -> str:\n    \"\"\"Ask the insurance desk whether a scheme (PM-JAY, CGHS) covers something.\"\"\"\n    return ask(\"insurance\", task)\n\n\nsupervisor = create_agent(\n    get_model(), [ask_scheduling, ask_billing, ask_insurance],\n    system_prompt=\"You are the City Clinic helpdesk supervisor. Delegate each part of the request to the right desk \"\n                  \"(in parallel when the parts are independent), then reply briefly using only their answers.\",\n    middleware=[ModelCallLimitMiddleware(run_limit=4)],\n)\n\nif __name__ == \"__main__\":\n    q = \"Can you explain BILL-2291, and does CGHS cover OPD visits?\"\n    out = supervisor.invoke({\"messages\": [(\"user\", q)]})\n    for m in out[\"messages\"]:\n        if m.type == \"ai\" and m.tool_calls:\n            print(\"supervisor ->\", [(c[\"name\"], c[\"args\"][\"task\"]) for c in m.tool_calls])\n        elif m.type == \"tool\":\n            print(f\"{m.name:<15}<- {m.content}\")\n    print(\"REPLY:\", out[\"messages\"][-1].content)\n","ch23/routing_eval.py":"\"\"\"Test the supervisor's ROUTING on its own: does each request go to the right specialist first?\n\nRouting mistakes are the commonest multi-agent bug, and they are cheap to test: one supervisor\ncall per case, no specialists needed.\n\nRun:  python routing_eval.py\n\"\"\"\nfrom supervisor_graph import SUPERVISOR, supervisor_model\n\nCASES = [\n    (\"Which days does Dr Khan see children?\", \"scheduling\"),\n    (\"Why is there an ECG charge on BILL-2291?\", \"billing\"),\n    (\"Does PM-JAY cover consumables?\", \"insurance\"),\n    (\"Is the OPD fee refundable?\", \"billing\"),\n    (\"Can I see the orthopaedics doctor on Tuesday?\", \"scheduling\"),\n    (\"Is CGHS accepted for surgery?\", \"insurance\"),\n    (\"My insurance claim for the ECG bill was rejected\", \"insurance\"),   # ambiguous: two topics\n    (\"Do you have a cafeteria?\", \"FINISH\"),          # no specialist: answer or hand over\n]\n\nif __name__ == \"__main__\":\n    correct = 0\n    for request, expected in CASES:\n        got = supervisor_model.invoke(f\"{SUPERVISOR}\\n\\nPatient: {request}\\nResults so far:\\nnone yet\").next\n        correct += got == expected\n        print(f\"{'ok ' if got == expected else 'BAD'} {request:<48} -> {got:<11} (expected {expected})\")\n    print(f\"\\nRouting accuracy: {correct}/{len(CASES)}\")\n","ch23/specialists.py":"\"\"\"Three specialist agents, each with ONLY its own tools and rules (Chapter 21's contracts).\n\nWrites are not tools here: the scheduling agent can only CHECK a slot. Booking happens later in\nthe graph, after a person approves (supervisor_graph.py). Agents propose; code and people dispose.\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nimport clinic  # noqa: E402\nfrom langchain.agents import create_agent  # noqa: E402\nfrom langchain.agents.middleware import ModelCallLimitMiddleware  # noqa: E402\nfrom langchain_core.tools import tool  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\n\nBILLS = {\"BILL-2291\": {\"OPD registration\": 100, \"ECG\": 350}}            # made-up data\nCOVERAGE = {\"pm-jay\": {\"covered\": [\"admission\", \"surgery\", \"ICU\"], \"not_covered\": [\"consumables\", \"attendant food\"]},\n            \"cghs\": {\"covered\": [\"OPD\", \"admission\", \"surgery\"], \"not_covered\": [\"cosmetic procedures\"]}}\n\n\n@tool\ndef get_doctor_schedule(department: str) -> dict:\n    \"\"\"Which doctors in a department see patients on which weekdays.\"\"\"\n    return clinic.get_doctor_schedule(department)\n\n\n@tool\ndef check_slot(doctor: str, day: str) -> dict:\n    \"\"\"Check that a doctor works on a weekday (e.g. Thu). Does NOT book anything.\"\"\"\n    for doctors in clinic.SCHEDULE.values():\n        if doctor in doctors:\n            return {\"doctor\": doctor, \"day\": day, \"available\": day[:3].title() in doctors[doctor], \"days\": doctors[doctor]}\n    return {\"error\": f\"No doctor called {doctor}\"}\n\n\n@tool\ndef get_bill(bill_id: str) -> dict:\n    \"\"\"Itemised charges for a bill number like BILL-2291.\"\"\"\n    items = BILLS.get(bill_id.upper())\n    return {\"bill_id\": bill_id.upper(), \"items\": items, \"total\": sum(items.values())} if items else {\"error\": \"Bill not found\"}\n\n\n@tool\ndef check_coverage(scheme: str, item: str) -> dict:\n    \"\"\"Whether an insurance scheme (pm-jay, cghs) covers an item such as surgery or consumables.\"\"\"\n    s = COVERAGE.get(scheme.lower().replace(\" \", \"-\"))\n    if not s:\n        return {\"error\": f\"Unknown scheme {scheme}\", \"known\": list(COVERAGE)}\n    covered, excluded = [c.lower() for c in s[\"covered\"]], [c.lower() for c in s[\"not_covered\"]]\n    status = \"covered\" if item.lower() in covered else \"not covered\" if item.lower() in excluded else \"unknown\"\n    return {\"scheme\": scheme, \"item\": item, \"status\": status}\n\n\nLIMIT = [ModelCallLimitMiddleware(run_limit=4, exit_behavior=\"end\")]   # every specialist has its own budget\nRULES = \" Use your tools; never guess. Never give medical advice. Reply in one or two sentences.\"\nSPECIALISTS = {\n    \"scheduling\": create_agent(get_model(), [get_doctor_schedule, check_slot], name=\"scheduling\", middleware=LIMIT,\n                               system_prompt=\"You are the City Clinic scheduling desk. You can check, not book.\" + RULES),\n    \"billing\": create_agent(get_model(), [get_bill], name=\"billing\", middleware=LIMIT,\n                            system_prompt=\"You are the City Clinic billing desk. Quote exact amounts from bills.\" + RULES),\n    \"insurance\": create_agent(get_model(), [check_coverage], name=\"insurance\", middleware=LIMIT,\n                              system_prompt=\"You are the City Clinic insurance desk. 'unknown' means ask the desk.\" + RULES),\n}\n\n\ndef ask(specialist: str, task: str) -> str:\n    \"\"\"Run a specialist on a task with a FRESH, private context: it sees the task, nothing else.\"\"\"\n    out = SPECIALISTS[specialist].invoke({\"messages\": [(\"user\", task)]})\n    return out[\"messages\"][-1].content\n","ch23/supervisor_graph.py":"\"\"\"A supervisor multi-agent system in LangGraph, with a human gate before any booking.\n\nsupervisor  -> decides the next specialist (or the booking gate, or FINISH) and writes its task\nspecialist  -> runs with a private context, returns a short result to the shared 'results' list\napprove     -> interrupt(): a person approves the booking proposed by the supervisor\nbook        -> plain code makes the booking request; no model can skip the gate\nRouting uses Command(goto=...): the node itself says where to go next.\n\nRun:  python supervisor_graph.py\n\"\"\"\nimport operator\nimport sys\nfrom pathlib import Path\nfrom typing import Annotated, Literal, TypedDict\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE.parent))\nsys.path.insert(0, str(HERE.parent / \"ch09\"))\nfrom clinic import request_appointment  # noqa: E402\nfrom langgraph.checkpoint.memory import InMemorySaver  # noqa: E402\nfrom langgraph.graph import END, START, StateGraph  # noqa: E402\nfrom langgraph.types import Command, interrupt  # noqa: E402\nfrom lc_models import get_model  # noqa: E402\nfrom pydantic import BaseModel  # noqa: E402\nfrom specialists import ask  # noqa: E402\n\nMAX_STEPS = 6\n\n\nclass Booking(BaseModel):\n    doctor: str\n    day: str\n    patient_name: str\n\n\nclass Decision(BaseModel):\n    next: Literal[\"scheduling\", \"billing\", \"insurance\", \"approve_booking\", \"FINISH\"]\n    task: str = \"\"                     # instruction for the specialist\n    booking: Booking | None = None     # only with approve_booking\n    reply: str = \"\"                    # only with FINISH: the answer for the patient\n\n\nclass State(TypedDict, total=False):\n    request: str\n    results: Annotated[list[str], operator.add]     # shared: each specialist appends one line\n    steps: int\n    task: str                                       # the supervisor's instruction for the next specialist\n    booking: dict\n    reply: str\n\n\nsupervisor_model = get_model().with_structured_output(Decision)\nSUPERVISOR = (\"You are the City Clinic helpdesk supervisor. Specialists: scheduling (doctor days, checking slots), \"\n              \"billing (bills, fees), insurance (scheme coverage). Give each specialist one clear task. \"\n              \"If the patient wants to book and the slot was checked, choose approve_booking with the booking. \"\n              \"When you have everything, choose FINISH and write a short reply using only the specialists' results.\")\n\n\ndef supervisor(state: State) -> Command:\n    if state.get(\"steps\", 0) >= MAX_STEPS:                       # Chapter 21 guard\n        return Command(goto=END, update={\"reply\": \"Let me connect you with our front desk (1800-000-000).\"})\n    results = \"\\n\".join(state.get(\"results\", [])) or \"none yet\"\n    d = supervisor_model.invoke(f\"{SUPERVISOR}\\n\\nPatient: {state['request']}\\nResults so far:\\n{results}\")\n    update = {\"steps\": state.get(\"steps\", 0) + 1}\n    if d.next == \"FINISH\":\n        return Command(goto=END, update={**update, \"reply\": d.reply})\n    if d.next == \"approve_booking\":\n        return Command(goto=\"approve\", update={**update, \"booking\": d.booking.model_dump()})\n    return Command(goto=d.next, update={**update, \"task\": d.task})\n\n\ndef make_specialist(name: str):\n    def node(state: State) -> Command:\n        answer = ask(name, state[\"task\"])\n        return Command(goto=\"supervisor\", update={\"results\": [f\"{name}: {answer}\"]})\n    return node\n\n\ndef approve(state: State) -> Command:\n    decision = interrupt({\"approve_booking\": state[\"booking\"]})          # pause for a person\n    if decision.get(\"approved\"):\n        return Command(goto=\"book\")\n    return Command(goto=\"supervisor\", update={\"results\": [f\"staff: booking declined ({decision.get('reason', '')})\"]})\n\n\ndef book(state: State) -> Command:\n    b = state[\"booking\"]\n    result = request_appointment(b[\"doctor\"], b[\"day\"], b[\"patient_name\"])\n    return Command(goto=\"supervisor\", update={\"results\": [f\"booking: {result}\"]})\n\n\nbuilder = StateGraph(State)\nbuilder.add_node(\"supervisor\", supervisor, destinations=(\"scheduling\", \"billing\", \"insurance\", \"approve\", END))\nfor name in (\"scheduling\", \"billing\", \"insurance\"):\n    builder.add_node(name, make_specialist(name), destinations=(\"supervisor\",))\nbuilder.add_node(\"approve\", approve, destinations=(\"book\", \"supervisor\"))\nbuilder.add_node(\"book\", book, destinations=(\"supervisor\",))\nbuilder.add_edge(START, \"supervisor\")\ngraph = builder.compile(checkpointer=InMemorySaver())\n\nif __name__ == \"__main__\":\n    cfg = {\"configurable\": {\"thread_id\": \"asha-1\"}}\n    out = graph.invoke({\"request\": \"I'm Asha Verma. Book me with Dr Rao on Thursday, and does PM-JAY cover surgery?\"}, cfg)\n    for line in out.get(\"results\", []):\n        print(\"  result:\", line)\n    print(\"PAUSED:\", out[\"__interrupt__\"][0].value)\n\n    out = graph.invoke(Command(resume={\"approved\": True}), cfg)          # staff approves\n    print(\"  result:\", out[\"results\"][-1])\n    print(\"REPLY:\", out[\"reply\"])\n    print(\"Supervisor steps:\", out[\"steps\"])\n","common/lc_models.py":"\"\"\"One place to create LangChain chat models and embeddings for every Part C chapter.\n\nLangChain hides the provider differences, so switching OpenAI <-> Anthropic is one line:\n\n    init_chat_model(\"openai:gpt-4.1-mini\")     or     init_chat_model(\"anthropic:claude-haiku-5-5\")\n\nThis helper reads the same .env settings as llm.py (PROVIDER, OPENAI_MODEL, ANTHROPIC_MODEL).\n\n    from lc_models import get_model, get_embeddings\n    model = get_model()                  # a LangChain chat model for your PROVIDER\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\nfrom langchain.chat_models import init_chat_model\nfrom langchain_core.embeddings import Embeddings\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\n\n\ndef get_model(provider: str | None = None, temperature: float = 0, **kwargs):\n    \"\"\"A chat model with sensible production defaults: a timeout and automatic retries.\"\"\"\n    provider = provider or PROVIDER\n    return init_chat_model(f\"{provider}:{MODELS[provider]}\", temperature=temperature,\n                           timeout=float(os.getenv(\"LLM_TIMEOUT\", \"30\")),\n                           max_retries=int(os.getenv(\"LLM_RETRIES\", \"2\")), **kwargs)\n\n\nclass CourseEmbeddings(Embeddings):\n    \"\"\"Wraps llm.embed() (Chapter 6) so LangChain vector stores can use it.\n    EMBEDDINGS=openai uses text-embedding-3-small; EMBEDDINGS=local uses a free local model.\"\"\"\n\n    def embed_documents(self, texts: list[str]) -> list[list[float]]:\n        from llm import embed\n        return embed(texts)\n\n    def embed_query(self, text: str) -> list[float]:\n        return self.embed_documents([text])[0]\n\n\ndef get_embeddings() -> Embeddings:\n    return CourseEmbeddings()\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
